const items = $input.all();
const issues = [];

for (const item of items) {
  const perms = item.json.permissions || [];
  const fileName = item.json.name || 'Unknown';
  const fileId = item.json.id || '';

  for (const perm of perms) {
    if (perm.type === 'anyone') {
      issues.push({ fileName, fileId, issue: 'Public access', role: perm.role, type: perm.type, severity: 'HIGH' });
    } else if (perm.type === 'domain') {
      issues.push({ fileName, fileId, issue: 'Domain-wide access', role: perm.role, domain: perm.domain, severity: 'MEDIUM' });
    } else if (perm.role === 'owner' && perm.type === 'user') {
      // Owner is expected, skip
    } else if (perm.role === 'writer' || perm.role === 'organizer') {
      issues.push({ fileName, fileId, issue: 'Editor access', role: perm.role, email: perm.emailAddress, severity: 'LOW' });
    }
  }
}

return issues.length > 0 ? issues.map(i => ({ json: i })) : [{ json: { noIssues: true, message: 'No over-sharing detected', auditedAt: new Date().toISOString() } }];
